import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"服务器相关/Docker/Redis.md","filePath":"服务器相关/Docker/Redis.md"}'),n={name:"服务器相关/Docker/Redis.md"};function i(p,e,l,o,d,c){return s(),r("div",null,[...e[0]||(e[0]=[t('<h3 id="取最新版的-redis-镜像" tabindex="-1">取最新版的 Redis 镜像 <a class="header-anchor" href="#取最新版的-redis-镜像" aria-label="Permalink to &quot;取最新版的 Redis 镜像&quot;">​</a></h3><p>这里我们拉取官方的最新版本的镜像：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker pull redis:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://www.runoob.com/wp-content/uploads/2016/06/docker-redis3.png" target="_blank" rel="noreferrer"><img src="https://s2.loli.net/2025/02/17/p8cIPWwrVMvTnkA.png" alt="img"></a></p><h3 id="_3、查看本地镜像" tabindex="-1">3、查看本地镜像 <a class="header-anchor" href="#_3、查看本地镜像" aria-label="Permalink to &quot;3、查看本地镜像&quot;">​</a></h3><p>使用以下命令来查看是否已安装了 redis：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker images</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://www.runoob.com/wp-content/uploads/2016/06/docker-redis4.png" target="_blank" rel="noreferrer"><img src="https://s2.loli.net/2025/02/17/Te8xPfXIR2GSyYz.png" alt="img"></a></p><p>在上图中可以看到我们已经安装了最新版本（latest）的 redis 镜像。</p><h3 id="_4、运行容器" tabindex="-1">4、运行容器 <a class="header-anchor" href="#_4、运行容器" aria-label="Permalink to &quot;4、运行容器&quot;">​</a></h3><p>安装完成后，我们可以使用以下命令来运行 redis 容器：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker run -itd --name redis-test -p 6379:6379 redis</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>参数说明：</p><ul><li><strong>-p 6379:6379</strong>：映射容器服务的 6379 端口到宿主机的 6379 端口。外部可以直接通过宿主机ip:6379 访问到 Redis 的服务。</li></ul><p><a href="https://www.runoob.com/wp-content/uploads/2016/06/docker-redis5.png" target="_blank" rel="noreferrer"><img src="https://s2.loli.net/2025/02/17/MHvRb3rf2jkKxsh.png" alt="img"></a></p><h3 id="_5、安装成功" tabindex="-1">5、安装成功 <a class="header-anchor" href="#_5、安装成功" aria-label="Permalink to &quot;5、安装成功&quot;">​</a></h3><p>最后我们可以通过 <strong>docker ps</strong> 命令查看容器的运行信息：</p><p><a href="https://www.runoob.com/wp-content/uploads/2016/06/docker-redis6.png" target="_blank" rel="noreferrer"><img src="https://s2.loli.net/2025/02/17/FWjRbehcINloa68.png" alt="img"></a></p><p>接着我们通过 redis-cli 连接测试使用 redis 服务。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker exec -it redis-test /bin/bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="https://www.runoob.com/wp-content/uploads/2016/06/docker-redis7.png" target="_blank" rel="noreferrer"><img src="https://s2.loli.net/2024/09/29/Xbkc1CDWlGQoEpZ.png" alt="img"></a></p>',21)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
